-- Demo Price Books for BPMSquare Pricing: a catalogue list, formula pricing and
-- cost plus. Targets the is_demo tenant only. Idempotent. GENERATED by
-- scripts/gen-pricing-demo-seed.ts from scripts/pricing-demo-books.ts -- edit
-- those and re-run `npx jiti scripts/gen-pricing-demo-seed.ts`, not this file.
--
-- RUN FIRST (in this order):
--   migrations  0083, 0098, 0099, 0100, 0111, 0113, 0114, 0115, 0121
--   seeds       scripts/seed-products-demo.sql   (this script keys on its products)
-- Optional, compatible: scripts/seed-pricing-cost-based-demo.sql (the cost-based walk).
--
-- What it does, per demo tenant that has the demo products:
--   1. Turns on pricing_engine, pricing_engine_quotes, products and standard_quotes.
--   2. Adds one product: Cabin Wall Panel — Stainless Steel (per m²), so there is something priced by area.
--   3. Registers the dimensions the books match on (never re-weights existing ones).
--   4. Creates three PUBLISHED Price Books, each at version 1:
--        catalogue_2026   "Catalogue 2026 (list)"  list prices + volume bands + tier discount
--        formula_pricing  "Formula pricing"        formulas: volume bands, price per m2 x area, regional uplift
--        cost_plus        "Cost plus"              product cost + 25% (spares 35%, services 40%)
--      Re-running refreshes a book only while it is still the untouched version 1
--      this script made; a book someone edited or re-published in the app is left alone.
--   5. Seeds the cost rates the books read (only where the tenant has none).
--   6. Routes products to the books in tenants.config.pricing.routing (this script's
--      rules go first; other routing rules and default_area are kept as they are).
-- The "default" Price Book (made in the app by the cost-based walk) is not touched.
-- Quotations on the demo tenant resolve through the same routing: the demo is shown on
-- Standard Quotes, but nothing here can fence the Quotation button off.

do $seed$
declare
  v_t uuid;
  v_other int;
begin
  for v_t in select id from tenants where is_demo = true loop
    if not exists (select 1 from products where tenant_id = v_t and ref = 'PRD-0001') then
      raise notice 'Demo tenant % has no demo products. Run scripts/seed-products-demo.sql first; skipped.', v_t;
      continue;
    end if;

    -- 1. Flags
    update tenants
       set features = coalesce(features, '{}'::jsonb)
         || '{"pricing_engine": true, "pricing_engine_quotes": true, "products": true, "standard_quotes": true}'::jsonb
     where id = v_t;

    -- 2. The area-priced product (ref = next free PRD number)
    insert into products (tenant_id, ref, name, sku, category, sub_category, uom, description, list_price, cost_price, tax_percent, status)
    select v_t,
           'PRD-' || lpad((coalesce((select max(substring(ref from '^PRD-([0-9]+)$')::int) from products where tenant_id = v_t), 0) + 1)::text, 4, '0'),
           'Cabin Wall Panel — Stainless Steel (per m²)', 'CAB-SS-M2', 'MODERNISATION', 'CABINS', 'Sqm', 'Brushed stainless steel cabin wall panel, priced by area (quantity = m²)', 6200, 4100, 18, 'active'
     where not exists (select 1 from products where tenant_id = v_t and sku = 'CAB-SS-M2');

    -- 3. Dimensions (tenant-wide vocabulary; existing weights win)
    insert into pricing_dimensions (tenant_id, attribute, weight, label)
    select v_t, d.attribute, d.weight, d.label from (values
      ('customer.tier', 30, 'Customer tier'),
      ('region', 20, 'Region'),
      ('document_type', 15, 'Document type'),
      ('product.base_model', 60, 'Product'),
      ('product.sub_category', 40, 'Product sub-category'),
      ('product.category', 30, 'Product category')
    ) as d(attribute, weight, label)
    on conflict (tenant_id, attribute) do nothing;

    -- 5. Cost rates (a rate already on file for the model and path wins)
    insert into pricing_cost_inputs (tenant_id, cost_model_code, path, kind, value, uom, source, source_code, quality, as_of)
    select v_t, c.model, c.path, c.kind, c.value, c.uom, 'MANUAL', 'MANUAL', 'estimate', current_date from (values
      ('STANDARD_COST', 'material.rate_per_unit', 'MATERIAL', 1250, null::text),
      ('STANDARD_COST', 'labour.rate_per_hour', 'LABOUR', 1800, null::text),
      ('STANDARD_COST', 'salvage.credit_per_unit', 'SALVAGE_CREDIT', 1200, null::text),
      ('CATALOG_FALLBACK_COST', 'material.rate_per_unit', 'MATERIAL', 10, null::text),
      ('CATALOG_FALLBACK_COST', 'material.ss_panel_per_m2', 'MATERIAL', 5200, null::text)
    ) as c(model, path, kind, value, uom)
    where not exists (
      select 1 from pricing_cost_inputs i
       where i.tenant_id = v_t and i.cost_model_code = c.model and i.path = c.path and i.product_id is null
    );

    -- 4. The Price Books
    -- Catalogue 2026 (list)  (area catalogue_2026, shaped like the "Price list" template)
    select count(*) into v_other from pricing_config_versions
     where tenant_id = v_t and pricing_area = 'catalogue_2026'
       and not (version = 1 and coalesce(notes, '') like 'Demo seed:%');
    if v_other > 0 then
      raise notice 'Price Book % already has versions this seed did not make; left untouched.', 'catalogue_2026';
    else
      delete from pricing_rules       where tenant_id = v_t and pricing_area = 'catalogue_2026' and config_version = 1;
      delete from pricing_components  where tenant_id = v_t and pricing_area = 'catalogue_2026' and config_version = 1;
      delete from pricing_procedures  where tenant_id = v_t and pricing_area = 'catalogue_2026' and config_version = 1;
      delete from pricing_cost_models where tenant_id = v_t and pricing_area = 'catalogue_2026' and config_version = 1;
      delete from pricing_config_versions where tenant_id = v_t and pricing_area = 'catalogue_2026' and version = 1;

      insert into pricing_config_versions (tenant_id, pricing_area, version, status, dsl_version, notes, published_at)
      values (v_t, 'catalogue_2026', 1, 'PUBLISHED', 1, $n$Demo seed: Catalogue 2026 (list) — list prices for elevators, goods lifts and AMC plans; OEM and direct customers get a tier discount.$n$, now());

      insert into pricing_components (tenant_id, pricing_area, config_version, code, name, class, calc_type, calc_basis, sign, rounding_rule, manual_override, is_statistical, resolution_strategy)
      select v_t, 'catalogue_2026', 1, c.* from (values
      ('LIST_PRICE', 'List price', 'PRICE', 'SCALE_TIERED', 'QUANTITY', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('CUST_DISC', 'Customer discount', 'DISCOUNT', 'PERCENT', 'NET_SO_FAR', 'NEGATIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('FREIGHT', 'Freight', 'FREIGHT', 'FIXED_AMOUNT', 'NET_SO_FAR', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('TAX', 'Tax', 'TAX', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', $j${"precision":2,"mode":"HALF_UP"}$j$::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC')
      ) as c(code, name, class, calc_type, calc_basis, sign, rounding_rule, manual_override, is_statistical, resolution_strategy);

      insert into pricing_procedures (tenant_id, pricing_area, config_version, code, name, entry_mode, steps)
      values (v_t, 'catalogue_2026', 1, 'PRICE_LIST', 'Price list', 'LIST_DOWN', $j$[{"step":10,"component":"LIST_PRICE","required":true},{"step":20,"component":"CUST_DISC","requirement":"dsl:ctx.customer.tier != null"},{"step":30,"subtotal":"NET_1"},{"step":40,"component":"FREIGHT"},{"step":50,"subtotal":"NET_2"},{"step":60,"component":"TAX","calc_basis_ref":"NET_2"},{"step":70,"subtotal":"FINAL"}]$j$::jsonb);

      insert into pricing_rules (tenant_id, pricing_area, config_version, component_code, match_attributes, value, scale, formula, valid_from, origin)
      select v_t, 'catalogue_2026', 1, r.component, r.match, r.value, r.scale, r.formula, r.valid_from, 'MANUAL' from (values
      ('LIST_PRICE', $j${"product.base_model":"Passenger Elevator 8P (630 kg)"}$j$::jsonb, null::numeric, $j${"entries":[{"from":0,"value":1850000},{"from":3,"value":1813000}]}$j$::jsonb, null::text, date '2026-01-01'),
      ('LIST_PRICE', $j${"product.base_model":"Passenger Elevator 13P (1000 kg)"}$j$::jsonb, null::numeric, $j${"entries":[{"from":0,"value":2650000},{"from":3,"value":2597000}]}$j$::jsonb, null::text, date '2026-01-01'),
      ('LIST_PRICE', $j${"product.base_model":"Hydraulic Goods Lift 2T"}$j$::jsonb, null::numeric, $j${"entries":[{"from":0,"value":1150000},{"from":3,"value":1127000}]}$j$::jsonb, null::text, date '2026-01-01'),
      ('LIST_PRICE', $j${"product.base_model":"Home Lift 4P Compact"}$j$::jsonb, null::numeric, $j${"entries":[{"from":0,"value":1275000},{"from":3,"value":1249500}]}$j$::jsonb, null::text, date '2026-01-01'),
      ('LIST_PRICE', $j${"product.base_model":"Elevator AMC — Comprehensive"}$j$::jsonb, null::numeric, $j${"entries":[{"from":0,"value":96000},{"from":3,"value":91200},{"from":5,"value":86400}]}$j$::jsonb, null::text, date '2026-01-01'),
      ('LIST_PRICE', $j${"product.base_model":"Elevator AMC — Non-comprehensive"}$j$::jsonb, null::numeric, $j${"entries":[{"from":0,"value":54000},{"from":3,"value":51300},{"from":5,"value":48600}]}$j$::jsonb, null::text, date '2026-01-01'),
      ('CUST_DISC', $j${"customer.tier":"oem"}$j$::jsonb, 8::numeric, null::jsonb, null::text, null::date),
      ('CUST_DISC', $j${"customer.tier":"direct"}$j$::jsonb, 5::numeric, null::jsonb, null::text, null::date),
      ('CUST_DISC', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('FREIGHT', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('TAX', $j${}$j$::jsonb, 18::numeric, null::jsonb, null::text, null::date)
      ) as r(component, match, value, scale, formula, valid_from);
    end if;

    -- Formula pricing  (area formula_pricing, shaped like the "Catalog + Formula" template)
    select count(*) into v_other from pricing_config_versions
     where tenant_id = v_t and pricing_area = 'formula_pricing'
       and not (version = 1 and coalesce(notes, '') like 'Demo seed:%');
    if v_other > 0 then
      raise notice 'Price Book % already has versions this seed did not make; left untouched.', 'formula_pricing';
    else
      delete from pricing_rules       where tenant_id = v_t and pricing_area = 'formula_pricing' and config_version = 1;
      delete from pricing_components  where tenant_id = v_t and pricing_area = 'formula_pricing' and config_version = 1;
      delete from pricing_procedures  where tenant_id = v_t and pricing_area = 'formula_pricing' and config_version = 1;
      delete from pricing_cost_models where tenant_id = v_t and pricing_area = 'formula_pricing' and config_version = 1;
      delete from pricing_config_versions where tenant_id = v_t and pricing_area = 'formula_pricing' and version = 1;

      insert into pricing_config_versions (tenant_id, pricing_area, version, status, dsl_version, notes, published_at)
      values (v_t, 'formula_pricing', 1, 'PUBLISHED', 1, $n$Demo seed: Formula pricing — wire rope by volume band, cabin panels by area, both with a regional uplift; anything else falls back to the catalogue price.$n$, now());

      insert into pricing_components (tenant_id, pricing_area, config_version, code, name, class, calc_type, calc_basis, sign, rounding_rule, manual_override, is_statistical, resolution_strategy)
      select v_t, 'formula_pricing', 1, c.* from (values
      ('MATERIAL_RATE', 'Rate per unit', 'PRICE', 'FORMULA', 'CUSTOM_METRIC', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('FREIGHT', 'Freight', 'FREIGHT', 'FIXED_AMOUNT', 'NET_SO_FAR', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('MARGIN_MARKUP', 'Margin', 'MARKUP', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('MARGIN_FLOOR', 'Minimum acceptable margin', 'STATISTICAL', 'FIXED_AMOUNT', 'GROSS', 'POSITIVE', null::jsonb, 'FORBIDDEN', true, 'MOST_SPECIFIC'),
      ('CUST_DISC', 'Customer discount', 'DISCOUNT', 'PERCENT', 'NET_SO_FAR', 'NEGATIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('TAX', 'Tax', 'TAX', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', $j${"precision":2,"mode":"HALF_UP"}$j$::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC')
      ) as c(code, name, class, calc_type, calc_basis, sign, rounding_rule, manual_override, is_statistical, resolution_strategy);

      insert into pricing_procedures (tenant_id, pricing_area, config_version, code, name, entry_mode, steps)
      values (v_t, 'formula_pricing', 1, 'CATALOG_FORMULA', 'Catalog + Formula', 'LIST_DOWN', $j$[{"step":10,"component":"MATERIAL_RATE","required":true},{"step":20,"subtotal":"TOTAL_COST"},{"step":30,"component":"FREIGHT"},{"step":40,"subtotal":"LANDED_COST"},{"step":50,"component":"MARGIN_MARKUP","calc_basis_ref":"LANDED_COST"},{"step":60,"subtotal":"NET_1"},{"step":65,"component":"MARGIN_FLOOR","statistical":true,"guardrail":{"kind":"MARGIN_FLOOR","cost_subtotal":"LANDED_COST","revenue_subtotal":"NET_1","policy":"warn"}},{"step":70,"component":"CUST_DISC"},{"step":80,"subtotal":"NET_2"},{"step":90,"component":"TAX","calc_basis_ref":"NET_2"},{"step":100,"subtotal":"FINAL"}]$j$::jsonb);

      insert into pricing_cost_models (tenant_id, pricing_area, config_version, code, name, sources)
      values (v_t, 'formula_pricing', 1, 'CATALOG_FALLBACK_COST', 'Fallback cost inputs', $j$[]$j$::jsonb);

      insert into pricing_rules (tenant_id, pricing_area, config_version, component_code, match_attributes, value, scale, formula, valid_from, origin)
      select v_t, 'formula_pricing', 1, r.component, r.match, r.value, r.scale, r.formula, r.valid_from, 'MANUAL' from (values
      ('MATERIAL_RATE', $j${"product.sub_category":"ROPES"}$j$::jsonb, null::numeric, null::jsonb, $f$round(ctx.line.quantity * (ctx.line.quantity >= 500 ? 360 : (ctx.line.quantity >= 100 ? 390 : 420)) * (ctx.region == null ? 1 : (ctx.region == "Karnataka" ? 1 : 1.04)), 2)$f$::text, null::date),
      ('MATERIAL_RATE', $j${"product.sub_category":"CABINS"}$j$::jsonb, null::numeric, null::jsonb, $f$round(max(ctx.line.quantity * ctx.cost.material.ss_panel_per_m2 * (ctx.line.quantity >= 50 ? 0.92 : 1) * (ctx.region == null ? 1 : (ctx.region == "Karnataka" ? 1 : 1.04)), 18000), 2)$f$::text, null::date),
      ('MATERIAL_RATE', $j${}$j$::jsonb, null::numeric, null::jsonb, $f$ctx.line.product.list_price * ctx.line.quantity$f$::text, null::date),
      ('FREIGHT', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('MARGIN_MARKUP', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('MARGIN_FLOOR', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('CUST_DISC', $j${"customer.tier":"oem"}$j$::jsonb, 5::numeric, null::jsonb, null::text, null::date),
      ('CUST_DISC', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('TAX', $j${}$j$::jsonb, 18::numeric, null::jsonb, null::text, null::date)
      ) as r(component, match, value, scale, formula, valid_from);
    end if;

    -- Cost plus  (area cost_plus, shaped like the "Cost-based" template)
    select count(*) into v_other from pricing_config_versions
     where tenant_id = v_t and pricing_area = 'cost_plus'
       and not (version = 1 and coalesce(notes, '') like 'Demo seed:%');
    if v_other > 0 then
      raise notice 'Price Book % already has versions this seed did not make; left untouched.', 'cost_plus';
    else
      delete from pricing_rules       where tenant_id = v_t and pricing_area = 'cost_plus' and config_version = 1;
      delete from pricing_components  where tenant_id = v_t and pricing_area = 'cost_plus' and config_version = 1;
      delete from pricing_procedures  where tenant_id = v_t and pricing_area = 'cost_plus' and config_version = 1;
      delete from pricing_cost_models where tenant_id = v_t and pricing_area = 'cost_plus' and config_version = 1;
      delete from pricing_config_versions where tenant_id = v_t and pricing_area = 'cost_plus' and version = 1;

      insert into pricing_config_versions (tenant_id, pricing_area, version, status, dsl_version, notes, published_at)
      values (v_t, 'cost_plus', 1, 'PUBLISHED', 1, $n$Demo seed: Cost plus — product cost plus 25% (spares 35%, services 40%); a floor flags anything under 15%.$n$, now());

      insert into pricing_components (tenant_id, pricing_area, config_version, code, name, class, calc_type, calc_basis, sign, rounding_rule, manual_override, is_statistical, resolution_strategy)
      select v_t, 'cost_plus', 1, c.* from (values
      ('PURCHASE_COST', 'Bought-in cost', 'COST_BUILDUP', 'COST_ROLLUP', 'COST_REF', 'POSITIVE', null::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC'),
      ('MATERIAL_COST', 'Material cost', 'COST_BUILDUP', 'COST_ROLLUP', 'COST_REF', 'POSITIVE', null::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC'),
      ('LABOUR_COST', 'Labour cost', 'COST_BUILDUP', 'COST_ROLLUP', 'COST_REF', 'POSITIVE', null::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC'),
      ('SALVAGE_CREDIT', 'Salvage credit', 'COST_BUILDUP', 'COST_ROLLUP', 'COST_REF', 'NEGATIVE', null::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC'),
      ('FREIGHT', 'Freight', 'FREIGHT', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('HANDLING', 'Handling', 'SURCHARGE', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('MARGIN_MARKUP', 'Margin', 'MARKUP', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('CUST_DISC', 'Customer discount', 'DISCOUNT', 'PERCENT', 'NET_SO_FAR', 'NEGATIVE', null::jsonb, 'ALLOWED_WITH_REASON', false, 'MOST_SPECIFIC'),
      ('MARGIN_FLOOR', 'Minimum acceptable margin', 'STATISTICAL', 'FIXED_AMOUNT', 'GROSS', 'POSITIVE', null::jsonb, 'FORBIDDEN', true, 'MOST_SPECIFIC'),
      ('TAX', 'Tax', 'TAX', 'PERCENT', 'SUBTOTAL_REF', 'POSITIVE', $j${"precision":2,"mode":"HALF_UP"}$j$::jsonb, 'FORBIDDEN', false, 'MOST_SPECIFIC')
      ) as c(code, name, class, calc_type, calc_basis, sign, rounding_rule, manual_override, is_statistical, resolution_strategy);

      insert into pricing_procedures (tenant_id, pricing_area, config_version, code, name, entry_mode, steps)
      values (v_t, 'cost_plus', 1, 'COST_SIMULATOR', 'Cost-based', 'COST_UP', $j$[{"step":10,"component":"PURCHASE_COST","cost_model":"STANDARD_COST","rollup_kind":"PURCHASE"},{"step":20,"component":"MATERIAL_COST","cost_model":"STANDARD_COST","rollup_kind":"MATERIAL"},{"step":30,"component":"LABOUR_COST","cost_model":"STANDARD_COST","rollup_kind":"LABOUR"},{"step":40,"component":"SALVAGE_CREDIT","cost_model":"STANDARD_COST","rollup_kind":"SALVAGE_CREDIT"},{"step":50,"subtotal":"TOTAL_COST"},{"step":60,"component":"FREIGHT","calc_basis_ref":"TOTAL_COST"},{"step":70,"component":"HANDLING","calc_basis_ref":"TOTAL_COST"},{"step":80,"subtotal":"LANDED_COST"},{"step":90,"component":"MARGIN_MARKUP","calc_basis_ref":"LANDED_COST"},{"step":100,"subtotal":"NET_1"},{"step":105,"component":"MARGIN_FLOOR","statistical":true,"guardrail":{"kind":"MARGIN_FLOOR","cost_subtotal":"LANDED_COST","revenue_subtotal":"NET_1","policy":"warn"}},{"step":110,"component":"CUST_DISC"},{"step":120,"subtotal":"NET_2"},{"step":130,"component":"TAX","calc_basis_ref":"NET_2"},{"step":140,"subtotal":"FINAL"}]$j$::jsonb);

      insert into pricing_cost_models (tenant_id, pricing_area, config_version, code, name, sources)
      values (v_t, 'cost_plus', 1, 'STANDARD_COST', 'Standard cost', $j$[{"code":"PRODUCT_COST","label":"ERP cost price on the product","tier":1,"quality":"actual","max_age_days":365},{"code":"RFQ","label":"Supplier RFQ reply","tier":2,"quality":"confirmed","max_age_days":180},{"code":"PRICE_LIST","label":"Imported cost price list","tier":3,"quality":"list","max_age_days":365},{"code":"MANUAL","label":"Rate kept by hand in the cost model","tier":4,"quality":"estimate"}]$j$::jsonb);

      insert into pricing_rules (tenant_id, pricing_area, config_version, component_code, match_attributes, value, scale, formula, valid_from, origin)
      select v_t, 'cost_plus', 1, r.component, r.match, r.value, r.scale, r.formula, r.valid_from, 'MANUAL' from (values
      ('FREIGHT', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('HANDLING', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('MARGIN_MARKUP', $j${}$j$::jsonb, 25::numeric, null::jsonb, null::text, null::date),
      ('MARGIN_MARKUP', $j${"product.category":"SPARES"}$j$::jsonb, 35::numeric, null::jsonb, null::text, null::date),
      ('MARGIN_MARKUP', $j${"product.category":"SERVICES"}$j$::jsonb, 40::numeric, null::jsonb, null::text, null::date),
      ('CUST_DISC', $j${"customer.tier":"oem"}$j$::jsonb, 3::numeric, null::jsonb, null::text, null::date),
      ('CUST_DISC', $j${}$j$::jsonb, 0::numeric, null::jsonb, null::text, null::date),
      ('MARGIN_FLOOR', $j${}$j$::jsonb, 15::numeric, null::jsonb, null::text, null::date),
      ('TAX', $j${}$j$::jsonb, 18::numeric, null::jsonb, null::text, null::date)
      ) as r(component, match, value, scale, formula, valid_from);
    end if;

    -- 6. Routing: this script's rules first, everyone else's kept, default_area untouched
    update tenants
       set config = jsonb_set(
         coalesce(config, '{}'::jsonb), '{pricing}',
         coalesce(config->'pricing', '{}'::jsonb) || jsonb_build_object('routing',
           coalesce(config#>'{pricing,routing}', '{}'::jsonb) || jsonb_build_object('rules',
             $r$[{"attribute":"product.sub_category","value":"ROPES","area":"formula_pricing"},{"attribute":"product.sub_category","value":"CABINS","area":"formula_pricing"},{"attribute":"product.category","value":"ELEVATORS","area":"catalogue_2026"},{"attribute":"product.category","value":"GOODS_LIFTS","area":"catalogue_2026"},{"attribute":"product.category","value":"SERVICE_PLANS","area":"catalogue_2026"},{"attribute":"product.category","value":"MODERNISATION","area":"cost_plus"},{"attribute":"product.category","value":"SERVICES","area":"cost_plus"},{"attribute":"product.category","value":"SPARES","area":"cost_plus"}]$r$::jsonb
             || coalesce((
               select jsonb_agg(x)
                 from jsonb_array_elements(coalesce(config#>'{pricing,routing,rules}', '[]'::jsonb)) x
                where x->>'area' not in ('catalogue_2026', 'formula_pricing', 'cost_plus')
             ), '[]'::jsonb)
           )
         )
       )
     where id = v_t;
  end loop;
end
$seed$;

-- Check: three published books per demo tenant, with their rule counts.
select t.slug, v.pricing_area, v.version, v.status,
       (select count(*) from pricing_rules r where r.tenant_id = v.tenant_id and r.pricing_area = v.pricing_area and r.config_version = v.version) as rules
  from pricing_config_versions v
  join tenants t on t.id = v.tenant_id
 where t.is_demo = true and v.pricing_area in ('catalogue_2026', 'formula_pricing', 'cost_plus')
 order by t.slug, v.pricing_area;
